CREATE   TRIGGER cad.TR_BlockPosition_CadGuard
ON cad.BlockPosition
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN prj.Project p ON p.ProjectId = i.ProjectId
        WHERE p.Status <> 2
    )
        THROW 50021, 'Project is not handed over to CAD (Status must be 2).', 1;
END;
