PRINT N'Creating Trigger [prj].[TR_ProjectProduct_CadGuard]...';


GO
CREATE   TRIGGER prj.TR_ProjectProduct_CadGuard
ON prj.ProjectProduct
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF IS_ROLEMEMBER(N'cad_plugin') = 1 AND IS_SRVROLEMEMBER(N'sysadmin') = 0
    BEGIN
        -- Block deleting MANUAL rows
        IF EXISTS (SELECT 1 FROM deleted d WHERE d.SourceKind <> 'CAD')
            THROW 50022, 'CAD plugin cannot delete non-CAD (MANUAL) ProjectProduct rows.', 1;

        -- Block deleting or modifying when Project.Status <> 2
        IF EXISTS (
            SELECT 1
            FROM (SELECT ProjectId FROM inserted UNION SELECT ProjectId FROM deleted) x
            JOIN prj.Project p ON p.ProjectId = x.ProjectId
            WHERE p.Status <> 2
        )
            THROW 50021, 'Project is not handed over to CAD (Status must be 2).', 1;
    END;
END;
GO
PRINT N'Creating Trigger [prod].[TR_ItemVariantValue_UniqueSiblingCombo]...';


GO
CREATE   TRIGGER prod.TR_ItemVariantValue_UniqueSiblingCombo
ON prod.ItemVariantValue
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- Keep prod.Item.VariantKeyHash synchronized for affected variant items
    ;WITH AffectedItems AS (
        SELECT DISTINCT i.ItemId, i.ParentId
        FROM inserted ins
        JOIN prod.Item i ON i.ItemId = ins.ItemId
        WHERE i.IsVariant = 1 AND i.ParentId IS NOT NULL AND i.IsDeleted = 0
    ),
    ComputedKeys AS (
        SELECT
            a.ItemId,
            STRING_AGG(CAST(v.AxisId AS nvarchar(16)) + N'=' + UPPER(LTRIM(RTRIM(v.CodeSuffix))), N'|')
                WITHIN GROUP (ORDER BY ax.SortOrder, v.AxisId) AS KeyHash
        FROM AffectedItems a
        JOIN prod.ItemVariantValue v ON v.ItemId = a.ItemId
        JOIN dict.VariantAxis ax ON ax.AxisId = v.AxisId
        GROUP BY a.ItemId
    )
    UPDATE i
    SET i.VariantKeyHash = ck.KeyHash
    FROM prod.Item i
    JOIN ComputedKeys ck ON ck.ItemId = i.ItemId;
END;
GO
PRINT N'Creating View [cad].[v_PositionEffectiveSku]...';


GO
-- 11. Views: cad.v_PositionEffectiveSku and cad.v_ProjectBom
CREATE   VIEW cad.v_PositionEffectiveSku AS
SELECT
    bp.TenantId,
    bp.ProjectId,
    bp.PositionId,
    bp.ZoneId,
    bp.DrawingId,
    bp.CadCatId,
    bp.BlockId,
    bp.PositionCode,
    bp.BlockName,
    bp.LayerName,
    bp.Quantity AS BaseQuantity,
    bp.Unit,
    po.PlanId,
    po.OptionCode,
    po.OptionName,
    COALESCE(pps.SkuId, bps.SkuId) AS EffectiveSkuId,
    COALESCE(pps.ItemId, bps.ItemId) AS EffectiveItemId,
    COALESCE(pps.GeneratedSku, bps.GeneratedSku) AS EffectiveSku,
    COALESCE(pps.SpecSummary, bps.SpecSummary) AS EffectiveSpecSummary,
    COALESCE(pps.UnitPrice, bps.UnitPrice) AS EffectiveUnitPrice,
    COALESCE(pps.QuantityOverride, bp.Quantity) AS EffectiveQuantity,
    CASE WHEN pps.PositionPlanSkuId IS NOT NULL THEN 1 ELSE 0 END AS IsOverriddenInPlan
FROM cad.BlockPosition bp
JOIN prj.ProjectPlanOption po
  ON po.TenantId = bp.TenantId AND po.ProjectId = bp.ProjectId
LEFT JOIN cad.PositionPlanSku pps
  ON pps.TenantId = bp.TenantId AND pps.PositionId = bp.PositionId AND pps.PlanId = po.PlanId
LEFT JOIN prj.ProjectPlanOption bpo
  ON bpo.TenantId = bp.TenantId AND bpo.ProjectId = bp.ProjectId AND bpo.IsBaseline = 1
LEFT JOIN cad.PositionPlanSku bps
  ON bps.TenantId = bp.TenantId AND bps.PositionId = bp.PositionId AND bps.PlanId = bpo.PlanId
WHERE bp.IsDeleted = 0;
GO
