PRINT N'Creating View [cad].[v_PositionEffectiveAttr]...';


GO
CREATE   VIEW cad.v_PositionEffectiveAttr
AS
SELECT
    bp.TenantId,
    bp.ProjectId,
    bp.ZoneId,
    bp.PositionId,
    bp.PositionCode,
    bp.BlockName,
    ad.AttrCode,
    ad.AttrNameEn,
    ad.UnitText,
    COALESCE(pav.AttrValue, zdef.AttrValue, pdef.AttrValue, ft.DefaultValue, ad.DefaultValue) AS EffectiveValue,
    CASE
        WHEN pav.AttrValue IS NOT NULL THEN 'POSITION'
        WHEN zdef.AttrValue IS NOT NULL THEN 'ZONE'
        WHEN pdef.AttrValue IS NOT NULL THEN 'PROJECT'
        WHEN ft.DefaultValue IS NOT NULL THEN 'TEMPLATE'
        ELSE 'GLOBAL_DEFAULT'
    END AS ValueSource,
    ISNULL(pav.ShowOnAnnoTag, 0) AS ShowOnAnnoTag
FROM cad.BlockPosition bp
CROSS JOIN cad.AttrDef ad
LEFT JOIN cad.BlockLibrary bl
    ON bl.BlockId = bp.BlockId AND bl.TenantId = bp.TenantId
LEFT JOIN cad.FixtureTypeAttrTemplate ft
    ON ft.TenantId = bp.TenantId
   AND ft.FixtureTypeCode = ISNULL(bl.FixtureTypeCode, SUBSTRING(bp.BlockName, 5, 64))
   AND ft.AttrCode = ad.AttrCode
LEFT JOIN cad.ScopeAttrDefault pdef
    ON pdef.TenantId = bp.TenantId
   AND pdef.ProjectId = bp.ProjectId
   AND pdef.ZoneId IS NULL
   AND pdef.AttrCode = ad.AttrCode
LEFT JOIN cad.ScopeAttrDefault zdef
    ON zdef.TenantId = bp.TenantId
   AND zdef.ProjectId = bp.ProjectId
   AND zdef.ZoneId = bp.ZoneId
   AND zdef.AttrCode = ad.AttrCode
LEFT JOIN cad.PositionAttrValue pav
    ON pav.TenantId = bp.TenantId
   AND pav.PositionId = bp.PositionId
   AND pav.AttrCode = ad.AttrCode
WHERE bp.IsDeleted = 0
  AND ad.TenantId = bp.TenantId
  AND ad.IsActive = 1;
GO
PRINT N'Creating View [inv].[v_SkuStockBalance]...';


GO
-- 3. Update [NEW] inv.v_SkuStockBalance to net Receipt (POSTED) minus Issue (POSTED)
--    (Exposes s.RecordId and m.GeneratedSku matching inv.SkuMaster columns exactly)
CREATE   VIEW inv.v_SkuStockBalance AS
WITH Movements AS (
    SELECT
        gr.TenantId,
        rd.SkuCode AS GeneratedSku,
        COALESCE(rd.WarehouseCode, gr.WarehouseCode) AS WarehouseCode,
        rd.Uom AS UomCode,
        rd.Qty AS ReceivedQty,
        CAST(0 AS decimal(18,2)) AS IssuedQty,
        gr.ReceiptDate AS MovementDate
    FROM inv.ReceiptDetail rd
    JOIN inv.GoodsReceipt gr ON gr.ReceiptId = rd.ReceiptId
    WHERE gr.Status = 'POSTED' AND rd.IsNoteRow = 0

    UNION ALL

    SELECT
        gi.TenantId,
        id.SkuCode AS GeneratedSku,
        COALESCE(id.WarehouseCode, gi.WarehouseCode) AS WarehouseCode,
        id.Uom AS UomCode,
        CAST(0 AS decimal(18,2)) AS ReceivedQty,
        id.Qty AS IssuedQty,
        gi.IssueDate AS MovementDate
    FROM inv.IssueDetail id
    JOIN inv.GoodsIssue gi ON gi.IssueId = id.IssueId
    WHERE gi.Status = 'POSTED' AND id.IsNoteRow = 0
)
SELECT
    m.TenantId,
    s.RecordId,
    m.GeneratedSku,
    m.WarehouseCode,
    m.UomCode,
    CAST(SUM(m.ReceivedQty) AS decimal(18,2)) AS TotalReceivedQty,
    CAST(SUM(m.IssuedQty) AS decimal(18,2)) AS TotalIssuedQty,
    CAST(SUM(m.ReceivedQty - m.IssuedQty) AS decimal(18,2)) AS OnHandQty,
    MAX(m.MovementDate) AS LastMovementDate
FROM Movements m
LEFT JOIN inv.SkuMaster s ON s.GeneratedSku = m.GeneratedSku AND s.TenantId = m.TenantId
GROUP BY
    m.TenantId,
    s.RecordId,
    m.GeneratedSku,
    m.WarehouseCode,
    m.UomCode;
GO
PRINT N'Creating View [cad].[v_ProjectBom]...';


GO
CREATE   VIEW cad.v_ProjectBom AS
SELECT
    TenantId,
    ProjectId,
    PlanId,
    OptionCode,
    OptionName,
    ZoneId,
    CadCatId,
    EffectiveSkuId AS SkuId,
    EffectiveItemId AS ItemId,
    EffectiveSku AS GeneratedSku,
    MAX(EffectiveSpecSummary) AS SpecSummary,
    Unit,
    SUM(EffectiveQuantity) AS TotalQuantity,
    COUNT(PositionId) AS PositionCount,
    MAX(EffectiveUnitPrice) AS UnitPrice,
    SUM(EffectiveQuantity * ISNULL(EffectiveUnitPrice, 0)) AS TotalAmount
FROM cad.v_PositionEffectiveSku
WHERE EffectiveSku IS NOT NULL
GROUP BY
    TenantId, ProjectId, PlanId, OptionCode, OptionName,
    ZoneId, CadCatId, EffectiveSkuId, EffectiveItemId, EffectiveSku, Unit;
GO
PRINT N'Creating Function [audit].[fn_ChangeHash]...';


GO
CREATE FUNCTION audit.fn_ChangeHash
(
    @PrevHash binary(32), @ChangeId bigint, @TenantId uniqueidentifier, @OccurredAt datetime2(7), @UserId uniqueidentifier,
    @EntityName varchar(128), @EntityKey nvarchar(128), @Action char(1), @BeforeJson nvarchar(max), @AfterJson nvarchar(max)
)
RETURNS binary(32)
WITH SCHEMABINDING
AS
BEGIN
    RETURN CAST(HASHBYTES('SHA2_256', CONCAT(
        CONVERT(varchar(64), @PrevHash, 2), N'|', @ChangeId, N'|', CONVERT(nvarchar(36), @TenantId), N'|',
        CONVERT(nvarchar(33), @OccurredAt, 126), N'|', CONVERT(nvarchar(36), @UserId), N'|',
        @EntityName, N'|', @EntityKey, N'|', @Action, N'|', @BeforeJson, N'|', @AfterJson)) AS binary(32));
END;
GO
