PRINT N'Creating Procedure [audit].[usp_VerifyChain]...';


GO
-- Returns the first ChangeId whose hash or link is broken (NULL = chain intact). Run as db_owner (sees all tenants).
CREATE PROCEDURE audit.usp_VerifyChain
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    WITH c AS (
        SELECT ChangeId, PrevHash, RowHash,
               LAG(RowHash, 1, 0x00) OVER (ORDER BY ChangeId) AS ExpectedPrev,
               audit.fn_ChangeHash(PrevHash, ChangeId, TenantId, OccurredAt, UserId, EntityName, EntityKey, Action, BeforeJson, AfterJson) AS Recomputed
        FROM audit.ChangeLog
    )
    SELECT MIN(ChangeId) AS FirstBrokenChangeId
    FROM c
    WHERE PrevHash <> ExpectedPrev OR RowHash <> Recomputed;
END;
GO
PRINT N'Creating Procedure [audit].[usp_AppendChange]...';


GO
-- Append-only writer: serialises appends, links each row to the previous hash.
CREATE PROCEDURE audit.usp_AppendChange
    @TenantId uniqueidentifier, @UserId uniqueidentifier, @EntityName varchar(128), @EntityKey nvarchar(128),
    @Action char(1), @BeforeJson nvarchar(max) = NULL, @AfterJson nvarchar(max) = NULL
WITH EXECUTE AS OWNER  -- must see the whole chain regardless of the caller's tenant (RLS)
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @session uniqueidentifier = CAST(SESSION_CONTEXT(N'TenantId') AS uniqueidentifier);
    IF @session IS NOT NULL AND (@TenantId IS NULL OR @TenantId <> @session)
        THROW 51001, 'audit: tenant mismatch with session', 1;
    BEGIN TRAN;
    DECLARE @lock int;
    EXEC @lock = sys.sp_getapplock @Resource = N'audit.ChangeLog', @LockMode = 'Exclusive', @LockOwner = 'Transaction', @LockTimeout = 10000;
    IF @lock < 0 THROW 51000, 'audit lock timeout', 1;
    DECLARE @prev binary(32) = ISNULL((SELECT TOP (1) RowHash FROM audit.ChangeLog ORDER BY ChangeId DESC), 0x00);
    DECLARE @now datetime2(7) = SYSUTCDATETIME();
    INSERT audit.ChangeLog (TenantId, OccurredAt, UserId, EntityName, EntityKey, Action, BeforeJson, AfterJson, PrevHash, RowHash)
    VALUES (@TenantId, @now, @UserId, @EntityName, @EntityKey, @Action, @BeforeJson, @AfterJson, @prev, 0x00);
    DECLARE @id bigint = SCOPE_IDENTITY();
    UPDATE audit.ChangeLog
       SET RowHash = audit.fn_ChangeHash(@prev, @id, @TenantId, @now, @UserId, @EntityName, @EntityKey, @Action, @BeforeJson, @AfterJson)
     WHERE ChangeId = @id;
    COMMIT;
    SELECT @id AS ChangeId;
END;
GO
PRINT N'Creating Procedure [sec].[usp_SetPassword]...';


GO
-- Admin only (NOT granted to app_platform): set a password hash computed by Speclight.Kernel.PasswordHasher.
CREATE PROCEDURE sec.usp_SetPassword
    @TenantCode varchar(32),
    @UserName   varchar(64),
    @Hash       varbinary(64),
    @Salt       varbinary(32),
    @Iterations int
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE u SET PasswordHash = @Hash, PasswordSalt = @Salt, PasswordIterations = @Iterations,
                 FailedLoginCount = 0, LockedUntil = NULL
    FROM plt.AppUser u JOIN plt.Tenant t ON t.TenantId = u.TenantId
    WHERE t.TenantCode = @TenantCode AND u.UserName = @UserName;
    IF @@ROWCOUNT <> 1 THROW 50010, 'User not found.', 1;
END;
GO
PRINT N'Creating Procedure [sec].[usp_DeleteRole]...';


GO
CREATE   PROCEDURE sec.usp_DeleteRole
    @RoleId int
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t uniqueidentifier = CAST(SESSION_CONTEXT(N'TenantId') AS uniqueidentifier);
    IF @t IS NULL THROW 50020, 'No session tenant.', 1;
    IF NOT EXISTS (SELECT 1 FROM plt.Role WHERE RoleId = @RoleId AND TenantId = @t)
        THROW 50021, 'Role is a template role or belongs to another tenant.', 1;
    BEGIN TRAN;
    DELETE FROM plt.UserRole WHERE RoleId = @RoleId AND TenantId = @t;
    DELETE FROM plt.RolePermission WHERE RoleId = @RoleId;
    DELETE FROM plt.Role WHERE RoleId = @RoleId AND TenantId = @t;
    COMMIT;
END;
GO
PRINT N'Creating Procedure [sec].[usp_GetLoginCandidate]...';


GO
-- V0010: login procedures. Login happens BEFORE a tenant is pinned, so RLS would hide plt.Tenant/AppUser.
-- These procs run AS OWNER with a narrow, fixed surface (one tenant code + one user name).
CREATE PROCEDURE sec.usp_GetLoginCandidate
    @TenantCode varchar(32),
    @UserName   varchar(64)
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SELECT t.TenantId, t.TenantCode, t.DisplayName AS TenantName, t.Status AS TenantStatus,
           u.UserId, u.UserName, u.DisplayName, u.PasswordHash, u.PasswordSalt, u.PasswordIterations,
           u.IsActive, u.LockedUntil, u.MustChangePassword
    FROM plt.Tenant t
    JOIN plt.AppUser u ON u.TenantId = t.TenantId
    WHERE t.TenantCode = @TenantCode AND u.UserName = @UserName;
END;
GO
PRINT N'Creating Procedure [sec].[usp_SaveRole]...';


GO
-- ---------- procs (session tenant pinned; owner context bypasses RLS, so every statement filters @t explicitly) ----------
CREATE   PROCEDURE sec.usp_SaveRole
    @RoleId      int = NULL,
    @RoleCode    varchar(32),
    @DisplayName nvarchar(200),
    @Permissions nvarchar(max) = N''   -- comma separated plt.Permission codes
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t uniqueidentifier = CAST(SESSION_CONTEXT(N'TenantId') AS uniqueidentifier);
    IF @t IS NULL THROW 50020, 'No session tenant.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@DisplayName, N'')))) = 0 OR LEN(LTRIM(RTRIM(ISNULL(@RoleCode, '')))) = 0 THROW 50023, 'Role name and code are required.', 1;
    IF @RoleId IS NOT NULL AND NOT EXISTS (SELECT 1 FROM plt.Role WHERE RoleId = @RoleId AND TenantId = @t)
        THROW 50021, 'Role is a template role or belongs to another tenant.', 1;
    DECLARE @codes TABLE (Code varchar(64) PRIMARY KEY);
    INSERT @codes SELECT DISTINCT LTRIM(RTRIM(value)) FROM STRING_SPLIT(ISNULL(@Permissions, N''), ',') WHERE LEN(LTRIM(RTRIM(value))) > 0;
    IF EXISTS (SELECT 1 FROM @codes c WHERE NOT EXISTS (SELECT 1 FROM plt.Permission p WHERE p.PermissionCode = c.Code))
        THROW 50022, 'Unknown permission code.', 1;
    BEGIN TRAN;
    IF @RoleId IS NULL
    BEGIN
        INSERT plt.Role (TenantId, RoleCode, DisplayName) VALUES (@t, @RoleCode, @DisplayName);
        SET @RoleId = CAST(SCOPE_IDENTITY() AS int);
    END
    ELSE
        UPDATE plt.Role SET DisplayName = @DisplayName WHERE RoleId = @RoleId AND TenantId = @t;
    DELETE FROM plt.RolePermission WHERE RoleId = @RoleId;
    INSERT plt.RolePermission (RoleId, PermissionCode) SELECT @RoleId, Code FROM @codes;
    COMMIT;
    SELECT @RoleId AS RoleId;
END;
GO
PRINT N'Creating Procedure [sec].[usp_SetUserRoles]...';


GO
CREATE   PROCEDURE sec.usp_SetUserRoles
    @UserId  uniqueidentifier,
    @RoleIds nvarchar(max) = N''   -- comma separated plt.Role ids (template or own tenant)
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    DECLARE @t uniqueidentifier = CAST(SESSION_CONTEXT(N'TenantId') AS uniqueidentifier);
    IF @t IS NULL THROW 50020, 'No session tenant.', 1;
    IF NOT EXISTS (SELECT 1 FROM plt.AppUser WHERE UserId = @UserId AND TenantId = @t) THROW 50024, 'User not found in this tenant.', 1;
    DECLARE @ids TABLE (RoleId int PRIMARY KEY);
    INSERT @ids SELECT DISTINCT TRY_CAST(value AS int) FROM STRING_SPLIT(ISNULL(@RoleIds, N''), ',') WHERE TRY_CAST(value AS int) IS NOT NULL;
    IF EXISTS (SELECT 1 FROM @ids i WHERE NOT EXISTS (SELECT 1 FROM plt.Role r WHERE r.RoleId = i.RoleId AND (r.TenantId IS NULL OR r.TenantId = @t)))
        THROW 50025, 'Role not visible to this tenant.', 1;
    BEGIN TRAN;
    DELETE FROM plt.UserRole WHERE UserId = @UserId AND TenantId = @t;
    INSERT plt.UserRole (UserId, RoleId, TenantId) SELECT @UserId, RoleId, @t FROM @ids;
    COMMIT;
END;
GO
PRINT N'Creating Procedure [sec].[usp_RecordLogin]...';


GO
-- Records the outcome: resets / increments FailedLoginCount (lock 15 min after 5 failures) + audit.LoginLog.
CREATE PROCEDURE sec.usp_RecordLogin
    @TenantId  uniqueidentifier,
    @UserId    uniqueidentifier,
    @UserName  varchar(64),
    @Succeeded bit,
    @Channel   varchar(16),
    @Detail    nvarchar(400) = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    IF @UserId IS NOT NULL
    BEGIN
        IF @Succeeded = 1
            UPDATE plt.AppUser SET FailedLoginCount = 0, LockedUntil = NULL WHERE UserId = @UserId;
        ELSE
            UPDATE plt.AppUser
            SET FailedLoginCount = FailedLoginCount + 1,
                LockedUntil = CASE WHEN FailedLoginCount + 1 >= 5 THEN DATEADD(MINUTE, 15, SYSUTCDATETIME()) ELSE LockedUntil END
            WHERE UserId = @UserId;
    END;
    INSERT audit.LoginLog (TenantId, UserName, Succeeded, Channel, Detail)
    VALUES (@TenantId, LEFT(@UserName, 64), @Succeeded, @Channel, @Detail);
END;
